    protected void Page_Load(object sender, EventArgs e)
    {
        Title = Sunplus.Accounting.Business.Report.Reports.Title;
        string strfdate = Request["fdate"];
        string str = "";
        keyReport += AppSession.AccUserName + strfdate;

        mode = Request["mode"];

        //Export to Excel
        string btnExport = Request["IsExport"];
        if (btnExport == "1")
        {
            string FileName = "NumberGameDailyWinloss-" + strfdate;
            var objData = AppSession.GetSession(Session, keyReport + "_excel");
            var data = string.Empty;
            if (objData != null)
            {
                data = objData.ToString();
            }
            else
            {
                data = RenderContent(strfdate);
            }
            ExportToExcel(FileName, data);
        }
        else
