            content.Text = RenderContent(strfdate);
        }
    }

    private string RenderContent(string fDate)
    {
        int count = 0;
        try
        {
            string header = "NUMBER GAME";
            string result = string.Empty;
            string excelResult = string.Empty;
            bool IsWL = CastAide.AsDateTime(fDate) > ReportUtils.BalanceUp.BalanceUpDay;
            const string sportname = "numbergame";
            const int sporttype = 161;

            Hashtable hash = null;
            string type = (string.IsNullOrEmpty(Request["type"])) ? string.Empty : Request["type"];

            DateTime wldate;

            #region Header

            int displaydays = 0;
            TimeSpan sp = DateTime.Today - ReportUtils.BalanceUp.BalanceUpDay;
            displaydays = sp.Days;
            string evt = "SetEvtGetdate()";
            string strDateTimeSingle = Sunplus.Accounting.Business.Report.Reports.GetDateTimeSingleWithoutGetDataFromRegion(fDate, "Date", string.Empty, displaydays, "../../../", string.Empty, evt);

            if (IsWL)
                TemplateHandler.Assign(ref strDateTimeSingle, "strDispday", "");
            else
                TemplateHandler.Assign(ref strDateTimeSingle, "strDispday", "none");

            string db = Request["db"];
            if (string.IsNullOrEmpty(db)) db = "Rep";
            if (db == "Rep")
            {
                TemplateHandler.Assign(ref strDateTimeSingle, "status-Rep", "checked=checked");
                TemplateHandler.Assign(ref strDateTimeSingle, "status-Main", "");
            }
            else
            {
                db = "Main";
                TemplateHandler.Assign(ref strDateTimeSingle, "status-Rep", "");
                TemplateHandler.Assign(ref strDateTimeSingle, "status-Main", "checked=checked");
            }
            TemplateHandler.Assign(ref strDateTimeSingle, "db", db);

            headerDatetime.Text = strDateTimeSingle;

            #endregion Header

            //headerDatetime.Text = Reports.GetHeader(strfdate, strtdate, path, true);
            DbResult rs;
            DataTable dtLive = new DataTable(), dtNoneLive = new DataTable();

            fDate = (string.IsNullOrEmpty(fDate)) ? DateTime.Today.ToShortDateString() : fDate;
            if (!Validator.ValidDateMMDDYYYY(fDate, out wldate).IsSuccess())
            {
                return "Invalid Date Format!!!";
            }

            IsBlankCell = false;
            int SiteID = string.IsNullOrEmpty(Request.Form["hiddenCompnayFilter"]) ? 0
                : CastAide.AsInt32(Request.Form["hiddenCompnayFilter"]);
            hiddenCompnayFilter.Value = string.IsNullOrEmpty(Request.Form["hiddenCompnayFilter"]) ? "0"
                : Request.Form["hiddenCompnayFilter"];

            int Currency = string.IsNullOrEmpty(Request.Form["hiddenCurrencyFilter"]) ? 0
                : CastAide.AsInt32(Request.Form["hiddenCurrencyFilter"]);
            hiddenCurrencyFilter.Value = string.IsNullOrEmpty(Request.Form["hiddenCurrencyFilter"]) ? "0"
                : Request.Form["hiddenCurrencyFilter"];

            if (CastAide.AsDateTime(fDate) > ReportUtils.BalanceUp.MoveBetsDay)
                rs = NumberGameWinLoss.WinlossByBetType(wldate, Currency, SiteID);
            else if (CastAide.AsDateTime(fDate) >= ReportUtils.BalanceUp.BalanceUpDay)
                rs = NumberGameWinLoss.WinlossByBetType14(wldate, SiteID, Currency);
            else
                rs = NumberGameWinLoss.WinlossByBetType_Old(wldate, SiteID, Currency);

            #region separate data Live and None Line

            dtLive = rs.ResultSet.Tables[0].Clone();
            dtNoneLive = rs.ResultSet.Tables[0].Clone();
            foreach (DataRow dr in rs.ResultSet.Tables[0].Rows)
            {
                if (CastAide.AsBoolean(dr["liveindicator"]))
                {
                    DataRow drNewLive = dtLive.NewRow();
                    for (int i = 0; i < dtLive.Columns.Count; i++)
                    {
                        drNewLive[i] = dr[i];
                    }
                    dtLive.Rows.Add(drNewLive);
                }
                else
                {
                    DataRow drNewNoneLive = dtNoneLive.NewRow();
                    for (int i = 0; i < dtNoneLive.Columns.Count; i++)
                    {
                        drNewNoneLive[i] = dr[i];
                    }
                    dtNoneLive.Rows.Add(drNewNoneLive);
                }
            }

            #endregion separate data Live and None Line

            string strTemp = string.Empty;
            strTemp = getcontent(0, header, dtNoneLive, 0);
            result += strTemp;
            if (dtNoneLive.Rows.Count > 0)
            {
                excelResult += strTemp;
            }
            if (dtNoneLive.Rows.Count > 0)
            {
                count++;
                result += "<span style='height:15px;'  id='spSplit'><br/><br/></span>";
                excelResult += "<span style='height:15px;'  id='spSplit'><br/><br/></span>";
            }

            strTemp = getcontent(1, header, dtLive, 0);
            result += strTemp;
            if (dtLive.Rows.Count > 0)
            {
                excelResult += strTemp;
            }
            if (dtLive.Rows.Count > 0) count++;

            //result += "</td></tr></table>";

            Footer.Text = GetFooter(fDate, fDate, sportname, sporttype.ToString(), Request["path"]);
            Footer.Text += AssignHidden();

            AppSession.AddSession(Session, keyReport, result);
            AppSession.AddSession(Session, keyReport + "_excel", excelResult);

            return result;

        }
        catch (Exception ex)
        {
            //string script = "<script type ='text/javascript'>";
            //script += "alert('" + IBCUtils.Encryption.RemoveSpecialChars(ex.Message) + "');";
            //script += "</script>";
            //Response.Write(script);
            Sunplus.Accounting.Core.Extensions.LogExtensions.ExceptionHandler(ex);
            return string.Empty;
        }
        finally
        {
            string script = "<script type ='text/javascript'>";
            script += "var count = " + count.ToString() + ";";
            script += "</script>";
            //Response.Write(script);
            jsfunction = script;
        }
    }

